  actions.myInfo=()=>{if(!auth())return;const d=dialog('Mes informations',`<form id="rProfileForm"><label>Nom et prénoms<input name="name" required maxlength="100" value="${esc(currentUser.name)}" autocomplete="name"></label><label>E-mail<input name="email" type="email" maxlength="180" value="${esc(currentUser.email||'')}" autocomplete="email"></label><p>Téléphone : ${esc(currentUser.phone||'Non renseigné')}</p><p class="r-note">Le téléphone de connexion se modifie auprès de l’organisation.</p><button type="submit" class="r-button blue">Enregistrer</button><p class="form-status" role="status"></p></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),status=f.querySelector('.form-status');b.disabled=true;try{const fields=new FormData(f),response=await fetch(API_BASE+'/api/users/me',{method:'PUT',headers:{Authorization:'Bearer '+userToken,'Content-Type':'application/json'},body:JSON.stringify({name:fields.get('name'),email:fields.get('email')})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Enregistrement impossible');currentUser=data.user;saveUserSession();renderProfileHeader();refreshHeaders();d.close();showToast('Informations enregistrées');}catch(error){status.textContent=error.message;}finally{b.disabled=false;}};};
