  const categoryFor = text => /sant[eé]|vaccin|m[eé]tier|exposition|formation/i.test(text)?'Culture':/danse|jeune|prestation|populaire/i.test(text)?'Animation':/roi|reine|c[eé]r[eé]mon|chef|apoth/i.test(text)?'Cérémonies':'Tradition';
